const guide = [{"id": "izdanje", "number": "", "navLabel": "Izdanje", "title": "Izdanje", "summary": "Informacije o izdanju, autorima, financiranju projekta i kontaktu.", "sections": [{"title": "Informacije o izdanju", "page": 2, "image": "pdf-images/image-002.png", "body": "<div class=\"pdf-text\">                            Udruga Penkala\n                            www.udruga-penkala.hr\n\nVodič za Znanstvenike povratnike dio je projekta „Mapa hrvatskih znanstvenika:\n  povezivanje i povratak” sufinanciranog od strane Ministarstva demografije i\nuseljeništva” u sklopu javnog poziva za financiranje posebnih potreba i projekata\n                       od interesa za hrvatsko useljeništvo.\n\n                U izradi su sudjelovali (abecednim redom):\n                                 Ana Budimir\n                           Una Pale Simon, dr. sc.\n                                 Luka Savić\n                             Nives Štrkalj, dr. sc.\n                        Katarina Radić (grafički dizajn)\n\n                          Izdanje: Lipanj 2026 Zagreb\n\n                                 Za sve upite:\n                            <a href=\"mailto:info@udruga-penkala.hr\" target=\"_blank\" rel=\"noreferrer\">info@udruga-penkala.hr</a></div>"}]}, {"id": "program", "number": "01", "title": "Znanstvenik povratnik", "summary": "Izvorni tekst iz PDF-a o programu i kriterijima.", "sections": [{"title": "Znanstvenik povratnik", "page": 3, "image": "pdf-images/image-003.png", "body": "<div class=\"pdf-text\">Znanstvenik povratnik\n&quot;Znanstvenik povratnik&quot; je ime koje se danas koristi za znanstvenike koji su\nsvoju znanstvenu karijeru nakon inozemstva odlučili nastaviti u Hrvatskoj.\n\nTo je bilo i ime programa osmišljenog i pokrenutog 2004. godine s ciljem\npoticanja hrvatskih znanstvenika koji djeluju u inozemstvu na povratak u\ndomovinu, i omogućujući im nastavak karijere u Hrvatskoj. S obzirom na\ndugotrajan problem odljeva mozgova (eng. Brain drain), ova mjera nastojala je\npotaknuti povratak istraživača u Hrvatsku te negativan trend pretvoriti u korisniji oblik\ncirkulacije mozgova (eng. Brain circulation), odnosno prijenosa znanja, iskustva i\nmeđunarodnih mreža stečenih izvan Hrvatske. Program je pružao podršku kroz\nodobravanje radnog mjesta te pokrivanje plaće znanstvenika povratnika na javnim\nsveučilištima i javnim znanstvenim institutima od strane Ministarstva znanosti,\nobrazovanja i mladih (MZOM).\n\nProgram se tijekom godina postupno razvijao i prilagođavao, osobito nakon revizije\nkriterija za prijavu 2018. godine. Međutim, promjene implementirane uvođenjem\nProgramskih ugovora          značajno su izmijenile njegovu strukturu i način\nprovedbe. Iz perspektive pojedinih dionika, time je prestao postojati u obliku u kojem je\nizvorno uspostavljen. Detaljnija analiza tih promjena prikazana je u nastavku.</div>"}, {"title": "Kategorija „Znanstvenik povratnik“", "page": 4, "image": "pdf-images/image-004.png", "body": "<div class=\"pdf-text\">Kategorija „Znanstvenik povratnik“\n\nPrije promjena koje su započele krajem 2023. godine, prema kojima se pozicije za\nznanstvenike povratnike moraju uvrstiti u Programske planove, ta su radna mjesta bila\nuređena sljedećim odlukama:\n\n   <a href=\"https://mzom.gov.hr/UserDocsImages/dokumenti/Znanost/PovratakZnanstvenika/4558046-Odluka%20o%20kriterijima%20za%20znanstvenike-povratnike(6576878).pdf\" target=\"_blank\" rel=\"noreferrer\">Odluka o kriterijima za odobravanje radnih mjesta znanstvenika-povratnika na\n   javnim sveučilištima i javnim znanstvenim institutima u Republici Hrvatskoj</a> (2018.)\n\n   <a href=\"https://mzom.gov.hr/UserDocsImages/dokumenti/Znanost/PovratakZnanstvenika/Odluka%20o%20izmjeni%20Odluke%20o%20kriterijima%20za%20odobravanje%20radnih%20mjesta%20znanstvenika%20-%20povratnika%20na%20javnim%20sveu%C4%8Dili%C5%A1tima%20i%20javnim%20znanstvenim%20institutima%20u%20Republici%20Hrvatskoj.pdf\" target=\"_blank\" rel=\"noreferrer\">Odluka o izmjeni Odluke o kriterijima za odobravanje radnih mjesta znanstvenika\n   povratnika</a> (2019.)\n\nAko su pozicije za znanstvenike povratnike predviđene u programskim ugovorima, one\nće u najvećem broju slučajeva slijediti prethodne smjernice.</div>"}, {"title": "Kriteriji za odobravanje radnih mjesta", "page": 5, "image": null, "body": "<div class=\"pdf-text\">Prema Odluci o kriterijima za odobravanje radnih mjesta znanstvenika-povratnika na\njavnim sveučilištima i javnim znanstvenim institutima, kandidat je trebao:\n\n\n\n       Ispunjavati kriterije za izbor na znanstveno-nastavno radno mjesto docenta ili\n       izvanrednog profesora, redovitog profesora ili redovitog profesora u trajnom\n       izboru.\n\n       Imati najmanje četiri godine radnog iskustva u sustavu znanosti izvan Republike\n       Hrvatske ostvarenog po stjecanju akademske titule doktora znanosti.\n\n       Iznimno, imati najmanje dvije godine radnog iskustva, ukoliko je završio doktorski\n       studij na sveučilištu koje se nalazi unutar prvih 300 sveučilišta, sukladno\n       posljednje objavljenoj listi Academic Ranking of World Universities („Šangajska\n       lista“) te dodatno biti znanstveno angažiran u trajanju od najmanje dvije godine na\n       nekom od navedenih sveučilišta.\n\n       Iznimno, ukoliko je kandidat, bilo hrvatski, bilo strani državljanin, voditelj projekta\n       Europskog istraživačkog vijeća, ostvareno radno iskustvo može biti i kraće od\n       četiri, odnosno dvije godine.\n\n       Iznimno, u slučaju da je kandidat strani državljanin, kandidat mora sudjelovati u\n       radu na projektu kojim u Republici Hrvatskoj može ostvariti financiranje svoga\n       istraživanja u razdoblju od najmanje godinu dana te imati najmanje tri godine\n       radnog iskustva na sveučilištima koja se nalaze unutar prvih 300 sveučilišta,\n       sukladno posljednje objavljenoj listi Academic Ranking of World Universities\n       („Šangajska lista“).</div>"}]}, {"id": "zakonski-okvir", "number": "02", "title": "Zakonski okvir", "summary": "Programski ugovori i nova logika zapošljavanja povratnika.", "sections": [{"title": "Programski ugovori i nova logika zapošljavanja povratnika", "page": 6, "image": null, "body": "<div class=\"pdf-text\">             Zakonski okvir\n             Programski ugovori i nova logika zapošljavanja povratnika\n\n             Donošenjem Zakona o visokom obrazovanju i znanstvenoj djelatnosti 2022.\n             godine uveden je novi model financiranja javnih sveučilišta i znanstvenih\n             instituta putem programskih ugovora.\n\n             Programski ugovori predstavljaju višegodišnje sporazume između Ministarstva\n             znanosti, obrazovanja i mladih (MZOM) i javnih znanstvenih institucija, kojima\n             se unaprijed definiraju: razvojni ciljevi institucije, međunarodna suradnja, razvoj\n             infrastrukture, ali i plan zapošljavanja,financiranje radnih mjesta, te prioriteti\n             vezani uz internacionalizaciju i privlačenje talenata\n\n             Programski ugovori potpisivani su na period od 4 godine, uz reviziju nakon 2\n             godine. MZOM je potpisao prve ugovore sa znanstvenim institucijama u periodu\n             između kraja 2023. i kraja 2025. godine, te stoga programski ugovori ne ističu\n             svim institucijama u isto vrijeme.\n\n             Gdje pronaći programske ugovore?\n\n             Mnoge programske ugovore moguće je pronaći na web stranicama ministarstva\n             (primjeri u tablici niže), najčešće u obavijestima, a neke su i same institucije\n             objavile na svojim web stranicama (npr. Institut Ruđer Bošković).\n\n             Kratki pregled datuma potpisivanja i lokacija programskih ugovora je u nastavku.\n\n\n                                                                                                               PROGRAMSKI\n                                 INSTITUCIJA                                          DATUM POTPISIVANJA\n                                                                                                                 UGOVOR\n\n\n                             Sveučilište u Zagrebu                                       Studeni 2025.          Web MZOMa\n\n\n         Sveučilište u Osijeku, Sveučilište Sjever i Sveučilište u Splitu                Listopad 2025          Web MZOMa\n\n\n\nSveučilište u Dubrovniku, Sveučilište u Slavonskom Brodu, Sveučilište Jurja\n                                                                                         Listopad 2025          Web MZOMa\n           Dobrile u Puli, Sveučilište u Zadru i Sveučilište u Rijeci\n\n\n\nInstitut za oceanografiju i ribarstvo (Split) Ekonomski institut (Zagreb), Institut\nza razvoj i međunarodne odnose (Zagreb), Institut za medicinska istraživanja\ni medicinu rada (Zagreb), Hrvatski šumarski institut (Zagreb), Institut za fiziku\n                                                                                                           Nisu dostupni na webu\n (Zagreb), Institut za jadranske kulture i melioraciju krša (Split), Institut Ruđer\n                                                                                                           MZOMa, potrebno ih je\n   Bošković (Zagreb), Institut za društvena istraživanja (Zagreb), Institut za\n                                                                                         Prosinac 2023         potražiti na web\n   turizam (Zagreb), Institut za etnologiju i folkloristiku (Zagreb), Institut za\n                                                                                                           stranicama institucija, ili\narheologiju (Zagreb), Institut za hrvatski jezik(Zagreb), Tehničko veleučilište u                                    05 upitom\n                                                                                                               direktnim\n                                     Zagrebu</div>"}, {"title": "Što to znači za znanstvenike povratnike?", "page": 7, "image": null, "body": "<div class=\"pdf-text\">Što to znači za znanstvenike povratnike?\n\nZa znanstvenike povratnike ova promjena je posebno važna jer institucije sada\nunaprijed planiraju povratnička radna mjesta unutar svojih programskih ugovora,\numjesto prethodnog sustava gdje su se mjesta naknadno odobravala od strane\nMinistarstva prema potrebi.\n\nU praksi to znači da:\n    institucije imaju veću autonomiju u planiranju zapošljavanja,\n    proces zapošljavanja može biti brži nego u starom modelu,\n    a strateško planiranje postaje ključni faktor za otvaranje novih povratničkih\n    pozicija.\n\nNo isto tako, sada mogućnost zapošljavanja znanstvenika povratnika uvelike\novisi o tome je li institucija unaprijed predvidjela takva radna mjesta u svom\nrazvojnom planu i programskom ugovoru.\n\nTo također znači da je rana komunikacija s institucijama postala još važnija\nnego prije. Budući povratnici trebaju kontaktirati potencijalne institucije dovoljno\nrano kako bi institucija mogla:\n   planirati odgovarajuće radno mjesto,\n   uključiti ga u buduće programske ugovore ili izmjene,\n   procijeniti istraživačko područje u koje se povratnik uključuje i povezati ga sa\n   strateškim prioritetima institucije,\n   te osigurati dugoročnu financijsku održivost pozicije.\n\nZa razliku od prethodnog sustava, u kojem je Ministarstvo odobravalo\npojedinačna mjesta nakon prijave kandidata, novi model više naglašava\nstrateško planiranje institucija. Kvaliteta odnosa između kandidata i institucije,\nuklapanje kandidata u razvojnu strategiju ustanove te mogućnost razvoja novih\nistraživačkih grupa ili projekata postaju još važniji elementi procesa povratka.</div>"}, {"title": "Institucionalni kapaciteti", "page": 8, "image": "pdf-images/image-005.png", "body": "<div class=\"pdf-text\">Institucionalni kapaciteti\n\nKapacitet za zapošljavanje znanstvenika povratnika danas se značajno razlikuje\nmeđu institucijama. Neke institucije aktivno koriste programske ugovore za\ninternacionalizaciju i razvoj novih istraživačkih područja kroz zapošljavanja\nznanstvenika povratnika ili stranih istraživača, dok druge imaju ograničen\nprostor za nova zapošljavanja zbog financijskih ili organizacijskih razloga.\n\nInstitucije koje već imaju aktivne međunarodne projekte, ERC ili Horizon Europe\ngrantove, razvijenu međunarodnu suradnju, te pozitivna iskustva sa\nzapošljavanjem znanstvenika povratnika ili privlačenja stranih istraživača u\nprošlosti, bile su otvorenije i uvrstile u programske ugovore i pozicije\nnamijenjene znanstvenicima povratnicima. Primjeri takvih institucija su: Institut\nza fiziku u Zagrebu, Institut Ruđer Bošković, Prirodoslovno-matematički fakultet\nu Zagrebu itd.\n\nVažno je naglasiti da povratnička mjesta više nisu nužno zasebna\nadministrativna kategorija, već se sve više integriraju u šire razvojne planove\ninstitucija. Stoga su mnoge institucije koje nisu imale interesa od strane\nznanstvenika povratnika u prošlosti, ostale suzdržane prema pozicijama\nposebno namijenjenim povratnicima.</div>"}]}, {"id": "proces", "number": "03", "title": "Koraci za povratak", "summary": "Proces povratka, pronalaženje pozicije, uvjeti i administrativni koraci.", "sections": [{"title": "Kako danas izgleda proces povratka?", "page": 9, "image": null, "body": "<div class=\"pdf-text\">Koraci za povratak\nKako danas izgleda proces povratka?\nIako se praksa razlikuje među institucijama, proces povratka danas najčešće\nizgleda ovako:\n\n 1. Kontaktiranje potencijalne institucije: Povratnici najčešće prvo kontaktiraju\n    istraživačke grupe ili pojedine profesore unutar institucije kako bi provjerili\n    postoji li interes i institucionalni kapacitet za zapošljavanje.\n\n 2. Procjena uklapanja u razvojne planove institucije: Institucija procjenjuje\n    uklapa li se kandidat u postojeće istraživačke prioritete, planove razvoja i\n    programski ugovor. Također, institucija provjerava postoji li dostupno radno\n    mjesto ili mogućnost njegova uključivanja u buduće planove zapošljavanja.\n\n 3. Pokretanje postupka izbora: Nakon dogovora, pokreće se formalni postupak\n    izbora u znanstveno ili znanstveno-nastavno radno mjesto koji se sastoji od\n    evaluacije kandidata putem povjerenstva i održavanja nastupnog\n    predavanja.\n\n 4. Priznavanje kvalifikacija i administrativni postupci: Kandidat paralelno, ili još\n    bolje unaprijed, pokreće postupke priznavanja diplome, eventualnog\n    priznavanja radnog staža i drugih administrativnih koraka.\n\n 5. Nakon odobrenja radnog mjesta na instituciji, Matični odbor polja odobrava\n    zapošljenje na radno mjesto tj. provjerava da kandidat zadovoljava\n    nacionalne kriterije. Kada institucija zaprimi odluku Matičnog odbora, slijedi\n    potpisivanje ugovora o zapošljavanju. Popis matičnih odbora dostupan je\n    <a href=\"https://nvvoztr.gov.hr/maticni-odbori/96\" target=\"_blank\" rel=\"noreferrer\">ovdje</a>.\n\nTrajanje cijelog procesa može značajno varirati među institucijama, ali je u\npravilu kraće nego u prethodnom sustavu pojedinačnih odobrenja Ministarstva\n(ukoliko je institucija predvidjela mjesto za povratnike ili vas može zaposliti na\nregularnu poziciju).\n\nU nastavku su pojedini koraci opisani detaljnije.</div>"}, {"title": "Pronalaženje pozicije", "page": 10, "image": "pdf-images/image-006.png", "body": "<div class=\"pdf-text\">Pronalaženje pozicije\nČak i one institucije koje su predvidjele povratnička mjesta rijetko raspisuju javne natječaje\nza povratnike prije razgovora s potencijalnim kandidatima jer su im ta mjesta od iznimne\nvažnosti, pa prije raspisivanja natječaja žele biti sigurni da će biti dobrih kandidata. Stoga\nje nulti korak kontaktirati istraživače iz srodnog područja na željenoj instituciji kako biste\nsaznali više informacija o prilikama i uvjetima na toj konkretnoj instituciji.\n\nKorisno pri kontaktiranju institucije razgovarati ne samo o samom zaposlenju, nego i o:\n    mogućnostima razvoja vlastite istraživačke grupe,\n    pristupu laboratorijima i infrastrukturi,\n    planovima institucije za internacionalizaciju,\n    mogućnostima prijave projekata,\n    te dugoročnoj karijernoj perspektivi.\n\nU mnogim slučajevima upravo sposobnost kandidata da doprinese strateškom razvoju\ninstitucije može igrati ključnu ulogu u odluci o zapošljavanju, a posebno kod institucija bez\npredviđenih povratničkih mjesta. U tom slučaju postoji mogućnost zapošljavanja na\nredovno mjesto, ili potencijalno prilikom revizije (za 2 godine) ili potpisivanja novih\nprogramskih ugovora (za 4 godine) uvrstiti vas u plan zapošljavanja.</div>"}, {"title": "Uvjeti za zapošljavanje", "page": 11, "image": null, "body": "<div class=\"pdf-text\">Uvjeti za zapošljavanje\nPosebno je važno razumjeti da se postupak izbora u Hrvatskoj sastoji od dva povezana, ali\nrazličita elementa:\n  1. Izbor u znanstveno zvanje (ispunjavanje nacionalnih kriterija propisanih zakonom i\n     Nacionalnim kriterijima),\n  2. Izbor na radno mjesto unutar institucije.\n\nIako su ta dva procesa povezana, oni nisu potpuno identični. Pojedine institucije mogu, uz\nnacionalne kriterije, propisati dodatne uvjete vezane uz svoje razvojne prioritete.\nPrimjerice:\n    osoba može zadovoljiti kriterije za određeno znanstveno zvanje,\n    ali institucija može imati dodatne uvjete za samo radno mjesto.\n\nTakvi dodatni uvjeti mogu uključivati:\n   nastavničko iskustvo,\n   mentoriranje doktoranada,\n   iskustvo vođenja projekata,\n   sposobnost privlačenja financiranja,\n   ili uklapanje u strateške prioritete institucije.\n\nStoga se preporučuje da potencijalni povratnici unaprijed prouče interne pravilnike željene\ninstitucije te razgovaraju s budućim kolegama o očekivanjima vezanim uz nastavu,\nmentoriranje i istraživačke aktivnosti.\n\nPopis trenutnih važećih propisa za izbor u radna mjesta moguće je pronaći na web\nstranicama institucija. Na primjer:\n    - Prehrambeno-biotehnološkog fakulteta u Zagrebu: <a href=\"https://pbf.unizg.hr/fakultet/dokumenti/opci_akti\" target=\"_blank\" rel=\"noreferrer\">ovdje</a>\n    - Institura Ruđer Bošković: <a href=\"https://www.irb.hr/O-IRB-u/Dokumenti/Statut-i-pravilnici/Pravilnici/Pravilnik-o-dodatnim-kriterijima-za-izbor-na-znanstvena-radna-mjesta\" target=\"_blank\" rel=\"noreferrer\">ovdje</a>\n    - Institut za Fiziku: <a href=\"https://ifs.hr/wp-content/uploads/2025/07/Pravilnik-o-dodatnim-kriterijima-za-izbor-i-reizbor-na-radna-mjesta_2025.pdf\" target=\"_blank\" rel=\"noreferrer\">ovdje</a></div>"}, {"title": "Prikupljanje dokumenata", "page": 12, "image": null, "body": "<div class=\"pdf-text\">Prikupljanje dokumenata\n\n           Potvrda o zastupljenosti i citiranosti radova:\nPotrebno je uputiti zahtjev Nacionalnoj i sveučilišnoj knjižnici u Zagrebu putem\n<a href=\"https://bibliometrija.nsk.hr/obrazac/\" target=\"_blank\" rel=\"noreferrer\">online obrasca</a> ili e-maila <a href=\"mailto:bibliometrijske.usluge@nsk.hr\" target=\"_blank\" rel=\"noreferrer\">bibliometrijske.usluge@nsk.hr</a>.\nUz zahtjev, prilaže se popis radova indeksiranih u Web of Science i/ili Scopusu. Kao svrhu\nzahtjeva potrebno je navesti “Znanstvenik povratnik”, a povratnu informaciju ćete dobiti u\nroku nekoliko dana. Naknada za ovu uslugu iznosi 13,27€.\n\n\n\n           Priznavanje inozemne diplome/doktorata:\n<a href=\"https://www.azvo.hr/inozemne-obrazovne-kvalifikacije/vrednovanje-inozemnih-visokoskolskih-kvalifikacija/\" target=\"_blank\" rel=\"noreferrer\">Agencija za znanost i visoko obrazovanje (AZVO)</a> provodi postupak vrednovanja\ninozemnih visokoškolskih kvalifikacija. Dokumentacija se šalje poštom, a postupak može\ntrajati nekoliko mjeseci, stoga je preporučljivo započeti ga što prije. Cijeli proces sastoji se\nod nekoliko koraka i dokumenata:\n\n    Pribavljanje ovjerenog prijevoda: Osigurajte ovjereni prijevod diplome doktora\n    znanosti i pratećih dokumenata na hrvatski ili engleski jezik. Ovjerene prijevode\n    izrađuju sudski tumači, a usluge možete pronaći putem servisa poput <a href=\"https://www.virtualni-asistent.hr/kontakti/\" target=\"_blank\" rel=\"noreferrer\">Virtualni asistent</a>.\n    Ovjera kopija: Napravite ovjerene kopije originalne diplome doktora znanosti,\n    pratećih dokumenata te prethodno stečenih visokoškolskih kvalifikacija kod javnog\n    bilježnika.\n    Dodatni dokumenti: Pripremite sljedeće: kopiju osobne iskaznice, izvornik\n    domovnice te životopis (na hrvatskom ili engleskom jeziku) koji uključuje popis\n    objavljenih radova.\n    Kronološki opis obrazovanja: Napišite kratki (jedan odlomak) kronološki prikaz\n    cjelokupnog obrazovanja.\n    Plaćanje administrativnih pristojbi: Uplatite potrebne administrativne pristojbe\n    prema uputama i priložite potvrdu o uplati uz prijavu.\n    Slanje dokumentacije: Potrebno je ispuniti zahtjev za vrednovanje koji se šalje sa\n    svom dokumentacijom poštom na adresu nadležne institucije tj. centra za vrednovanje.\n\nNapomena: Ako prateći dokumenti ne sadrže sve potrebne informacije, obratite se\ninstituciji na kojoj ste stekli doktorat kako bi vam izdali odgovarajuću potvrdu.</div>"}, {"title": "Priznavanje inozemnog staža", "page": 13, "image": null, "body": "<div class=\"pdf-text\">Priznavanje inozemnog staža\nPriznavanje inozemnog radnog staža u Hrvatskoj može utjecati na određena prava\nzaposlenika, poput povećanja plaće, broja dana godišnjeg odmora i ostvarivanja mirovine.\nPrema odredbama <a href=\"https://narodne-novine.nn.hr/clanci/sluzbeni/2024_03_29_458.html\" target=\"_blank\" rel=\"noreferrer\">Temeljnog kolektivnog ugovora za zaposlenike u javnim službama</a>,\nplaća se uvećava za 0,5% za svaku navršenu godinu radnog staža. Međutim, <a href=\"https://mrosp.gov.hr/print.aspx?id=7364\" target=\"_blank\" rel=\"noreferrer\">tumačenje\nbroj 50/2014</a> navodi da se staž proveden u inozemstvu računa se u radni staž za uvećenje\nplaće od 0,5% po godini, samo pod uvjetom da se isti staž računa u Republici Hrvatskoj u\nstaž osiguranja za mirovinu, dakle ako je to tako regulirano međunarodnim ugovorima\n(sporazumima) Republike Hrvatske i pojedinih drugih državama, ili se radi o stažu u\nzemljama Europske unije nakon 1. srpnja 2013.\n\nStoga je potrebno za priznavanje inozemnog staža mirovinskih prava, pokrenuti\npriznavanje inozemnog staža pri Hrvatskom zavodu za mirovinsko osiguranje (HZMO).\nPreporučuje se osobno podnijeti zahtjev za priznavanje inozemnog staža HZMO-u, uz\npriložene dokaze o stažu ostvarenome u inozemstvu. Ako već ne posjedujete dokumente,\nzamolite inozemne institucije za očitovanje, a HZMO će provesti postupak ispitivanja u\nstranim zemljama. Ako niste uspjeli nikakve dokumente prikupiti za pojedini period\nmoguće je i da neće biti nužni, pa kontaktirajte HZMO.\nOvisno o broju institucija i država na kojima ste radili, postupak može trajati nekoliko\nmjeseci. Nakon što dobijete odluku od HZMO-a, tu odluku nosite administraciji svoje\ntrenutne nove institucije.\n\nKorisne poveznice:\n  - <a href=\"https://www.mirovinsko.hr/hr/tiskanice/482\" target=\"_blank\" rel=\"noreferrer\">Pregled raznih zahtjeva na web stranicama Zavoda za mirovinsko osiguranje</a>\n  - <a href=\"https://www.mirovinsko.hr/UserDocsImages/tiskanice/Zahtjev_utvrdivanje_osiguranja_inozemstvo-1-6a.pdf?vel=292414\" target=\"_blank\" rel=\"noreferrer\">Zahtjev za utvrđivanje razdoblja osiguranja navršenih u inozemstvu</a>\n\n\nPar napomena\nBitno je napomenuti da iskustva znanstvenika povratnika ne moraju uvijek biti jednoznačno\npozitivna. Njihov dolazak u postojeće istraživačke sredine može otvoriti pitanja preklapanja\nistraživačkih područja, raspodjele resursa i percepcije konkurencije među kolegama. Ako\npovratnik dolazi s povoljnijim uvjetima financiranja radnog mjesta ili plaće, to u određenim\nokolnostima može izazvati nezadovoljstvo ili osjećaj neravnopravnosti unutar institucije.\nUpravo zato je važno da institucije povratak znanstvenika planiraju transparentno, uz jasno\ndefiniranje istraživačkog područja, uloge povratnika i načina njegova uključivanja u\npostojeću akademsku zajednicu.\n\nOdluka o povratku nikada nije jednostavna i zato preporučujemo da se pri donošenju takve\nodluke uzmu u obzir različiti profesionalni i osobni čimbenici: mogućnosti radnog mjesta,\nuvjeti za znanstveni razvoj, doprinos hrvatskoj akademskoj i istraživačkoj zajednici,\npovratak bližnjima, kvaliteta života — pa i blizina mora. :)</div>"}]}, {"id": "sustav", "number": "04", "title": "Sustav znanosti u Hrvatskoj", "summary": "Novi okvir za izbore, znanstvena zvanja i radna mjesta u Hrvatskoj.", "sections": [{"title": "Novi okvir za izbore u znanstvena i znanstveno-nastavna zvanja", "page": 14, "image": null, "body": "<div class=\"pdf-text\">Sustav znanosti u\nHrvatskoj\nNovi okvir za izbore u znanstvena i znanstveno-nastavna zvanja\n\nPosljednjih godina sustav izbora u znanstvena i znanstveno-nastavna zvanja u\nHrvatskoj prolazi kroz značajne promjene. Nakon donošenja <a href=\"https://narodne-novine.nn.hr/clanci/sluzbeni/2022_10_119_1834.html\" target=\"_blank\" rel=\"noreferrer\">Zakona o visokom\nobrazovanju i znanstvenoj djelatnosti</a> 2022. godine, Nacionalno vijeće za visoko\nobrazovanje, znanost i tehnološki razvoj donijelo je 2026. godine nove <a href=\"https://narodne-novine.nn.hr/clanci/sluzbeni/2026_04_42_506.html\" target=\"_blank\" rel=\"noreferrer\">Nacionalne\nsveučilišne, znanstvene i umjetničke kriterije (NN 42/2026)</a>, čime je usklađen zakonski\nokvir i uspostavljen jedinstven nacionalni okvir za izbore na znanstvena, znanstveno-\nnastavna, umjetničko-nastavna i nastavna radna mjesta.\n\nNovi kriteriji nastoje postići veću transparentnost i usporedivost postupaka izbora\nmeđu institucijama te vrednovati cjelokupni doprinos kandidata. Naglasak više nije\nisključivo na broju objavljenih radova, nego i na:\n     kvaliteti i međunarodnoj vidljivosti znanstvenog rada,\n     sudjelovanju i vođenju kompetitivnih projekata,\n     mentoriranju studenata i doktoranada,\n     nastavnom doprinosu,\n     institucijskom angažmanu,\n     međunarodnoj suradnji,\n     doprinosu razvoju znanstvene zajednice i društva.\n\nZa znanstvenike povratnike to predstavlja važnu promjenu jer međunarodno iskustvo,\nsudjelovanje u međunarodnim projektima i iskustvo rada u različitim istraživačkim\nsustavima mogu predstavljati značajnu prednost u postupku izbora.</div>"}, {"title": "Pregled znanstvenih zvanja i radnih mjesta u Hrvatskoj", "page": 15, "image": null, "body": "<div class=\"pdf-text\">Pregled znanstvenih zvanja i radnih mjesta u Hrvatskoj\n\n         Znanstvena zvanja\n  U Hrvatskoj su znanstvena zvanja organizirana u četiri razine:\n     Znanstveni suradnik (ZS)\n     Viši znanstveni suradnik (ZVS)\n     Znanstveni savjetnik (ZSV)\n     Znanstveni savjetnik u trajnom izboru (ZSV-T)\n\n  Nacionalni kriteriji iz 2026. godine uvode koncept „radnih mjesta po razinama“, pri\n  čemu se znanstvena zvanja i odgovarajuća znanstveno-nastavna zvanja promatraju\n  kao usporedive razine napredovanja:\n     razina 1: znanstveni suradnik / docent,\n     razina 2: viši znanstveni suradnik / izvanredni profesor,\n     razina 3: znanstveni savjetnik / redoviti profesor,\n     razina 4: znanstveni savjetnik u trajnom izboru / redoviti profesor u trajnom izboru.\n\n  Kriteriji za izbor razlikuju se među znanstvenim područjima, ali se temelje na\n  kombinaciji znanstvenih rezultata i kvalitativnih pokazatelja. U pojedinim područjima\n  uvedeni su i bodovni sustavi koji omogućuju vrednovanje različitih vrsta znanstvenih\n  doprinosa. Više informacija moguće je pronaći i na web stranicama <a href=\"https://mzom.gov.hr/istaknute-teme/znanost/znanstvenici/znanstvena-radna-mjesta/153\" target=\"_blank\" rel=\"noreferrer\">Ministarstva\n  znanosti i obrazovanja</a>.\n\n\n         Znanstvena radna mjesta\n  U sustavu znanosti i visokog obrazovanja postoje sljedeća znanstvena radna mjesta:\n\n      Asistent – početna pozicija u trajanju od 6 godina te uključuje i upisivanje\n      doktorskog studija. Asistenti su uključeni u provođenje vježbi i seminara na\n      fakultetskim radnim mjestima, dok su na institutima uključeni u istraživanje.\n\n      Asistent na projektu - ovisno o dobivenom projektu, može trajati 2-4 godine i može i\n      ne mora uključivati upis u doktorski studij\n\n      Viši asistent – radno mjesto namijenjeno istraživačima nakon stjecanja doktorata, u\n      maksimalnom trajanju od 4 godine. Struktura rada je slična kao i asistentsko\n      mjesto, uz veću samostalnos u istraživanju i nastavnim aktivnostima, a znači i veći\n      koeficijent place. U neku ruku to je je mjesto u čekanju docentskog mjesta ili\n      znanstvenog suradnika.\n\n      Znanstveni suradnik – prvo samostalno znanstveno radno mjesto nakon doktorata.\n\n      Viši znanstveni suradnik – viša razina samostalnog istraživačkog rada koja\n      podrazumijeva kontinuirana znanstvena postignuća.\n\n      Znanstveni savjetnik – najviše znanstveno radno mjesto prije trajnog izbora,\n      rezervirano za istraživače s istaknutim međunarodno prepoznatim doprinosom.\n\n      Znanstveni savjetnik u trajnom izboru – najviše znanstveno radno mjesto koje\n      predstavlja trajno priznanje dugogodišnjoj izvrsnosti i doprinosu znanstvenoj\n      zajednici.</div>"}, {"title": "Znanstveno nastavna radna mjesta", "page": 16, "image": null, "body": "<div class=\"pdf-text\">       Znanstveno nastavna radna mjesta\nNa sveučilištima znanstveni rad često je povezan s nastavnim obvezama. Znanstveno-\nnastavna radna mjesta uključuju:\n\n   Docent (doc.) – osnovno znanstveno-nastavno radno mjesto koje omogućuje\n   samostalno izvođenje nastave i provođenje istraživanja.\n   Izvanredni profesor (izv. prof.) – više radno mjesto koje podrazumijeva značajniji\n   doprinos znanosti i nastavi.\n   Redoviti profesor (prof.) – najviše znanstveno-nastavno radno mjesto prije trajnog\n   izbora.\n   Redoviti profesor u trajnom izboru – trajno zvanje koje odražava dugoročan i\n   izniman doprinos znanosti, nastavi i razvoju institucije.\n\nPosebnost novih kriterija iz 2026. godine jest da se za izbor na znanstveno-nastavna\nradna mjesta vrednuju tri skupine doprinosa:\n\nA. Nastavni doprinos\nPrimjeri uključuju:\n    mentoriranje završnih, diplomskih i doktorskih radova,\n    razvoj novih kolegija,\n    inovativne nastavne metode,\n    izradu nastavnih materijala,\n    sudjelovanje u unapređenju kvalitete nastave.\n\nB. Znanstveno-stručni doprinos\nPrimjeri uključuju:\n    vođenje ili sudjelovanje u kompetitivnim projektima,\n    međunarodne suradnje,\n    uredničke aktivnosti,\n    organizaciju znanstvenih skupova,\n    patente i transfer tehnologije,\n    stručni rad izvan akademske zajednice.\n\nC. Institucijski doprinos\nPrimjeri uključuju:\n    sudjelovanje u upravljačkim tijelima institucije,\n    razvoj novih studijskih programa,\n    vođenje laboratorija ili centara,\n    rad u nacionalnim i međunarodnim povjerenstvima.\n\nMinimalni broj uvjeta koje kandidat mora zadovoljiti razlikuje se ovisno o razini radnog\nmjesta. Primjerice, za izbor u zvanje docenta potrebno je zadovoljiti najmanje jedan\nuvjet iz nastavnog doprinosa i jedan uvjet iz znanstveno-stručnog doprinosa, dok se za\nviše razine očekuje veći broj ostvarenja u svim kategorijama.</div>"}, {"title": "Ostali oblici radnih mjesta na visokim učilištima", "page": 17, "image": "pdf-images/image-007.png", "body": "<div class=\"pdf-text\">       Ostali oblici radnih mjesta na visokim učilištima\n\nSustav visokog obrazovanja u Hrvatskoj obuhvaća i druge kategorije radnih mjesta:\n   znanstveno-nastavna i umjetničko-nastavna radna mjesta,\n   nastavna radna mjesta,\n   suradnička radna mjesta,\n   stručna radna mjesta.\n\nMapiranje između znanstvenih i znanstveno-nastavnih razina definirano je kako slijedi:\n   docent odgovara znanstvenom suradniku,\n   izvanredni profesor odgovara višem znanstvenom suradniku,\n   redoviti profesor odgovara znanstvenom savjetniku,\n   redoviti profesor u trajnom izboru odgovara znanstvenom savjetniku u trajnom\n   izboru.\n\nNastavna radna mjesta bez znanstvene komponente uključuju predavača, višeg\npredavača, profesora visoke škole, lektora i višeg lektora.\nSuradnička radna mjesta su asistent i viši asistent.\nStručna radna mjesta uključuju stručnog suradnika, višeg stručnog suradnika i\nstručnog savjetnika.</div>"}]}, {"id": "financije", "number": "05", "title": "Financijski aspekti", "summary": "Troškovi života, raspon plaća i mogućnosti dodatnih prihoda kroz projekte.", "sections": [{"title": "Procjena troškova života u Hrvatskoj", "page": 18, "image": null, "body": "<div class=\"pdf-text\">Financijski aspekti\nOvaj odjeljak pruža pregled raspona plaća za znanstvene pozicije, mogućnosti za\ndodatne prihode putem istraživačkih projekata te osnovnih troškova života, kako bi\npotencijalni kandidati mogli donijeti informiranu odluku.\n\nProcjena troškova života u Hrvatskoj\nTroškovi života u Hrvatskoj i dalje su niži nego u mnogim zapadnoeuropskim zemljama,\nno posljednjih godina došlo je do primjetnog rasta cijena, osobito kada je riječ o\nstanovanju. Visina troškova značajno ovisi o gradu, životnom stilu i veličini kućanstva.\nU nastavku donosimo okvirnu procjenu mjesečnih troškova za 2026. godinu:\n\n   Stanovanje: Najamnina za jednosobni ili manji dvosobni stan u Zagrebu najčešće\n   se kreće između 700 i 1.000 EUR mjesečno, ovisno o lokaciji i opremljenosti stana.\n   U manjim gradovima poput Osijeka, Slavonskog Broda ili Varaždina moguće je\n   pronaći stanove u rasponu od 450 do 700 EUR, dok su cijene u Splitu i Dubrovniku\n   često usporedive sa zagrebačkima ili više, osobito tijekom turističke sezone.\n   Režijski troškovi (struja, grijanje, voda, pričuva, internet i mobilne usluge) za jedno\n   kućanstvo najčešće iznose 100–200 EUR mjesečno.\n\n   Hrana: Mjesečni troškovi za namirnice za jednu odraslu osobu obično se kreću\n   između 250 i 400 EUR, ovisno o prehrambenim navikama i učestalosti prehrane\n   izvan kuće. Obitelj s djecom može očekivati znatno više troškove.\n\n   Prijevoz: Mjesečna karta za javni prijevoz u Zagrebu iznosi približno 40 EUR, dok\n   su troškovi korištenja osobnog automobila (gorivo, osiguranje i održavanje)\n   značajno viši.\n\n   Ukupni troškovi: Prosječni mjesečni troškovi života za samca u Zagrebu,\n   uključujući najam stana, režije i osnovne životne potrebe, najčešće se kreću između\n   1.300 i 1.800 EUR. Za obitelji s djecom ukupni troškovi mogu biti znatno viši, ovisno\n   o stambenim i obrazovnim potrebama.\n\nIako su troškovi života u Hrvatskoj porasli nakon uvođenja eura i razdoblja povećane\ninflacije, oni su i dalje niži nego u mnogim velikim gradovima zapadne Europe. Pri\nprocjeni financijske isplativosti povratka preporučuje se uzeti u obzir ne samo visinu\nplaće, nego i porezne olakšice za povratnike, mogućnosti dodatnih prihoda te osobne i\nobiteljske okolnosti.\n\nU usporedbi s plaćama znanstvenika, posebice onih na višim pozicijama ili s dodatnim\nprihodima od projekata, životni standard u Hrvatskoj može biti ugodan. Detaljniji iznosi\nna temelju povratnih informacija stanovnika moguće je pronaći <a href=\"https://www.numbeo.com/cost-of-living/in/Zagreb\" target=\"_blank\" rel=\"noreferrer\">ovdje</a>.</div>"}, {"title": "Raspon plaća za znanstvene pozicije", "page": 19, "image": null, "body": "<div class=\"pdf-text\">Raspon plaća za znanstvene pozicije\nPlaće zaposlenika u sustavu znanosti i visokog obrazovanja određuju se prema\njedinstvenom sustavu koeficijenata u javnim službama. Konačni neto iznos ovisi o\nradnom mjestu, radnom stažu, poreznom statusu, mjestu prebivališta i eventualnim\ndodacima.\n\nPrema okvirnim izračunima za 2026. godinu, neto plaće znanstvenog i znanstveno-\nnastavnog osoblja najčešće se kreću u sljedećim rasponima:\n   Razina 1: približno 2.000 – 2.200 EUR neto mjesečno\n   Razina 2: približno 2.200 – 2.900 EUR neto mjesečno\n   Razina 3: približno 2.900 – 3.300 EUR neto mjesečno\n   Razina 4: često iznad 3.300 EUR neto mjesečno,\n   ali ovisne su o stažu i dodacima.\n\nNa web stranicama Nezavisnog sindikata znanosti i visokog obrazovanja možete\npronaći i <a href=\"https://www.nsz.hr/kalkulator-place/\" target=\"_blank\" rel=\"noreferrer\">kalkulator plaća</a>.\n\nDodatne uloge unutar institucije poput vođenja grupe/laboratorija ili zavoda tj.\n„ustrojstvenih jedinica“ ili „samostalnih ustrojstvenih jedinica“, kao i sudjelovanje u\nravnateljstvu ili dekanatu/rektoratu su dodatno vrednovane kroz plaću.\n\nDodatno, <a href=\"https://narodne-novine.nn.hr/clanci/sluzbeni/2024_03_29_458.html\" target=\"_blank\" rel=\"noreferrer\">temeljnim ugovorom o plaćama u javnim službama</a>, zaposlenici ostvaruju\ndodatna prava kao što su: godišnji odmor do 30 dana (20 dana minimum + 5 dana za\nsloženost posla + 2 dana po djetetu + staž), regres (300 EUR u 2026.), Dar u prigodi\nDana sv. Nikole (100 EUR po djetetu u 2026.), Božićnica (300 EUR u 2026.), Godišnja\nnagrada za uskršnje blagdane (100 EUR u 2026.), etc.</div>"}, {"title": "Mogućnosti za dodatne prihode kroz projekte", "page": 20, "image": "pdf-images/image-008.png", "body": "<div class=\"pdf-text\">Mogućnosti za dodatne prihode kroz projekte\nOsim osnovne plaće, znanstvenici u Hrvatskoj mogu povećati svoje prihode\nsudjelovanjem u istraživačkim projektima i njihovoj evaluaciji. Nacionalni i međunarodni\nprojekti pružaju priliku za dodatno financiranje, razvoj istraživačke grupe i jačanje\nmeđunarodne suradnje. Ukoliko projekt dozvoljava, moguće je kroz njega povećati\nplaću do 30%.\n\nDodatni oblici financiranja uključuju i dnevnice, rad za vanjske dionike te isplate\ndodataka za rad na projektima (radni paketi).\n\nGlavni izvori financiranja uključuju:\n   <a href=\"https://hrzz.hr/en/funding/\" target=\"_blank\" rel=\"noreferrer\">Hrvatsku zakladu za znanost (HRZZ)</a> – financiranje temeljnih i primijenjenih\n   istraživanja;\n   <a href=\"https://research-and-innovation.ec.europa.eu/funding/funding-opportunities/funding-programmes-and-open-calls/horizon-europe_en\" target=\"_blank\" rel=\"noreferrer\">Horizon Europe</a> – najveći europski program za istraživanje i inovacije;\n        <a href=\"https://erc.europa.eu/apply-grant\" target=\"_blank\" rel=\"noreferrer\">ERC (European Research Council) grantove</a> – namijenjene istraživačima koji\n        razvijaju samostalne i ambiciozne istraživačke programe;\n        <a href=\"https://eic.ec.europa.eu/eic-funding-opportunities_en\" target=\"_blank\" rel=\"noreferrer\">EIC (European Innovation Council) grantove</a> – namijenjene istraživačima koji\n        razvijaju projekte s inovativnim potencijalom\n   <a href=\"https://www.cost.eu/what-do-we-fund/\" target=\"_blank\" rel=\"noreferrer\">COST akcije</a> – međunarodne istraživačke mreže koje omogućuju povezivanje\n   istraživača diljem Europe;\n   Bilateralne i multilateralne projekte – koji potiču suradnju s inozemnim\n   institucijama, npr. <a href=\"https://weave-research.net/\" target=\"_blank\" rel=\"noreferrer\">Weave calls</a>\n   ERA projekte za zemlje EU-13 koje još razvijaju znanstvene potencijale, na primjer:\n   <a href=\"https://rea.ec.europa.eu/funding-and-grants/horizon-europe-widening-participation-and-spreading-excellence/era-fellowships_en\" target=\"_blank\" rel=\"noreferrer\">Marie Curie WidERA</a>, <a href=\"https://rea.ec.europa.eu/funding-and-grants/horizon-europe-widening-participation-and-spreading-excellence/era-chairs_en\" target=\"_blank\" rel=\"noreferrer\">ERA Chairs</a>, <a href=\"https://www.m-era.net/\" target=\"_blank\" rel=\"noreferrer\">M-ERA</a>, <a href=\"https://quantera.eu/\" target=\"_blank\" rel=\"noreferrer\">Quantera</a>, itd.\n\nSudjelovanje u projektima ne doprinosi samo financijskoj stabilnosti, nego i povećava\nmeđunarodnu vidljivost, olakšava uspostavljanje novih suradnji te može otvoriti vrata\nbudućim istraživačkim i karijernim prilikama.</div>"}]}, {"id": "mjere", "number": "06", "title": "Ostale mjere za poticanje povratka u Hrvatsku", "summary": "Porezne olakšice, priznavanje kvalifikacija, potpore i financiranje istraživanja.", "sections": [{"title": "Porezne olakšice za povratnike", "page": 21, "image": "pdf-images/image-009.png", "body": "<div class=\"pdf-text\">Ostale mjere za poticanje\npovratka u Hrvatsku\nPosljednjih godina Republika Hrvatska uvodi sve više mjera kojima pokušava\nolakšati povratak hrvatskih državljana i useljenika iz inozemstva. Iako većina tih\nmjera nije specifično namijenjena znanstvenicima, mnoge mogu biti vrlo korisne\nistraživačima i njihovim obiteljima tijekom procesa povratka.\n\nOvaj pregled ne zamjenjuje službene informacije institucija, ali može pomoći pri\norijentaciji u dostupnim mogućnostima.\n\n\n         Porezne olakšice za povratnike\n\nJedna od najvažnijih mjera za povratnike odnosi se na oslobođenje od poreza\nna dohodak. Prema aktualnom zakonodavnom okviru, hrvatski državljani,\niseljenici i njihovi potomci koji su određeno vrijeme živjeli u inozemstvu mogu\nostvariti pravo na oslobođenje od plaćanja poreza na dohodak od\nnesamostalnog rada tijekom prvih pet godina nakon povratka.\n\nUvjeti i administrativni postupci mogu se mijenjati, pa je preporučljivo pratiti\ninformacije Ministarstva financija, te konzultirati Poreznu upravu prije\npreseljenja. Više informacija o uvjetima i postupku prijave dostupne su u\n<a href=\"https://mvep.gov.hr/oslobodjenje-od-poreza-na-dohodak-na-pet-godina-nova-mjera-za-povratnike/274946?utm_source=chatgpt.com\" target=\"_blank\" rel=\"noreferrer\">informativnom biltenu Ministarstva financija</a>.\n\nZa znanstvenike koji dolaze iz država s drugačijim poreznim sustavima posebno\nje važno provjeriti:\n    pitanja dvostrukog oporezivanja,\n    status porezne rezidentnosti,\n    te moguće porezne obveze prema državi iz koje dolaze.</div>"}, {"title": "Priznavanje inozemnih diploma i kvalifikacija", "page": 22, "image": null, "body": "<div class=\"pdf-text\">         Priznavanje inozemnih diploma i kvalifikacija\n\nPovratnici koji su završili studij ili doktorat u inozemstvu često moraju proći\npostupak priznavanja inozemnih kvalifikacija. Postupak uključuje:\n   administrativnu provjeru diploma,\n   prijevode dokumentacije,\n   te vrednovanje kvalifikacija.\n\nVažno je naglasiti da postupci mogu trajati više mjeseci, pa se preporučuje\nzapočeti ih što ranije.\n\nU posljednje vrijeme država pokušava pojednostaviti i ubrzati pojedine dijelove\nprocesa, osobito za povratnike i deficitarna zanimanja. Osim toga Ministarstvo\ndemografije i useljeništva testira i <a href=\"https://mdu.gov.hr/javni-poziv-za-financiranje-troskova-prijevoda-inozemnih-visokoskolskih-kvalifikacija-na-hrvatski-jezik-za-hrvatske-iseljenike-njihove-potomke-i-clanove-obitelji-u-2026-godini-pilot-projekt/7504\" target=\"_blank\" rel=\"noreferrer\">pilotni projekt</a> za financiranje troškova\nprijevoda inozemnih visokoškolskih kvalifikacija na hrvatski jezik.\n\n\n\n\n         Natječaji i potpore <a href=\"https://mdu.gov.hr/\" target=\"_blank\" rel=\"noreferrer\">Ministarstva</a> demografije i useljeništva\n\nMinistarstvo demografije i useljeništva posljednjih godina pokreće programe\nusmjerene prema povratnicima i useljenicima. Takvi programi mogu uključivati:\n   financiranje troškova preseljenja,\n   potpore za integraciju,\n   sufinanciranje troškova života,\n   potporu za priznavanje kvalifikacija,\n   te različite oblike pomoći pri uključivanju u hrvatsko društvo i tržište rada.\n\nBudući da se natječaji i uvjeti redovito mijenjaju, preporučuje se pratiti:\n   službene stranice Ministarstva,\n   portal e-Građani,\n   te stranice <a href=\"https://hrvatiizvanrh.gov.hr/\" target=\"_blank\" rel=\"noreferrer\">Središnjeg državnog ureda za Hrvate izvan Republike Hrvatske</a>.</div>"}, {"title": "Potpore za samozapošljavanje i poduzetništvo", "page": 23, "image": null, "body": "<div class=\"pdf-text\">          Potpore za samozapošljavanje i poduzetništvo\n\nPovratnici koji žele razvijati vlastite projekte, konzultantske aktivnosti ili startupove mogu\nkoristiti i <a href=\"https://<a href=\"https://mjere.hzz.hr/katalog-mjera/mjere-aktivnog-zaposljavanja/\" target=\"_blank\" rel=\"noreferrer\">mjere</a>.hzz.hr/mjere/potpore-za-samozaposljavanje-2026/\" target=\"_blank\" rel=\"noreferrer\">programe samozapošljavanja</a>.\n\nHrvatski zavod za zapošljavanje (HZZ) redovito raspisuje mjere koje uključuju:\n   potpore za pokretanje poslovanja,\n   subvencioniranje doprinosa,\n   edukacije,\n   mentorsku podršku\n   te posebne programe namijenjene povratnicima, poput mjere „Biram Hrvatsku“.\n\nMjera „Biram Hrvatsku“ namijenjena je, između ostalog, hrvatskim državljanima koji se\nvraćaju iz inozemstva i žele pokrenuti vlastitu djelatnost u Hrvatskoj. Važno je naglasiti da\nje ova mjera dio aktivnih politika zapošljavanja te da se na njih mogu prijaviti osobe\nprijavljene u evidenciju nezaposlenih osoba HZZ-a. Uz bespovratna sredstva za\nsamozapošljavanje, u određenim slučajevima moguće je ostvariti i dodatnu financijsku\npotporu za preseljenje i život u manje razvijenim područjima Republike Hrvatske.\n\nTakve mjere mogu biti posebno zanimljive:\n   znanstvenicima koji žele pokrenuti spin-off tvrtke,\n   konzultantske djelatnosti,\n   deep-tech startupove,\n   ili privatne istraživačke inicijative.\n\n\n         Financiranje istraživanja nakon povratka\n\nZa mnoge povratnike ključno pitanje nije samo zaposlenje nego i mogućnost financiranja\nistraživanja.\nU Hrvatskoj glavni izvori financiranja uključuju:\n     <a href=\"https://hrzz.hr/en/project-application/open-calls/\" target=\"_blank\" rel=\"noreferrer\">Hrvatsku zakladu za znanost</a> (HRZZ),\n     <a href=\"https://research-and-innovation.ec.europa.eu/funding/funding-opportunities/funding-programmes-and-open-calls/horizon-europe_en\" target=\"_blank\" rel=\"noreferrer\">Horizon Europe</a>,\n          ERC/EIC grantove,\n     bilateralne projekte,\n     <a href=\"https://www.cost.eu/what-do-we-fund/\" target=\"_blank\" rel=\"noreferrer\">COST akcije</a>,\n     te različite nacionalne i europske infrastrukturne programe.\n\nZa znanstvenike koji dolaze iz međunarodnog sustava često je korisno već prije povratka:\n    identificirati moguće izvore financiranja,\n    razgovarati s institucijama o projektnoj podršci,\n    te procijeniti administrativne kapacitete institucije za vođenje međunarodnih projekata.</div>"}]}, {"id": "resursi", "number": "07", "title": "Korisni resursi za znanstvenike povratnike", "summary": "Pregled institucija, portala i izvora informacija.", "sections": [{"title": "Zapošljavanje u sustavu znanosti i visokog obrazovanja", "page": 24, "image": null, "body": "<div class=\"pdf-text\">Korisni resursi za\nznanstvenike povratnike\nKako bi proces povratka bio što jednostavniji, u nastavku donosimo pregled najkorisnijih\ninstitucija, portala i izvora informacija. Budući da se propisi i natječaji redovito mijenjaju,\npreporučuje se provjeriti aktualne informacije na službenim mrežnim stranicama.\n\n\nZapošljavanje u sustavu znanosti i visokog obrazovanja\n    Ministarstvo znanosti, obrazovanja i mladih (MZOM)\nInformacije o zakonodavnom okviru, programskim ugovorima i sustavu visokog\nobrazovanja. <a href=\"https://mzom.gov.hr/\" target=\"_blank\" rel=\"noreferrer\">https://mzom.gov.hr/</a>\n\n   Narodne novine – Nacionalni sveučilišni, znanstveni i umjetnički kriteriji (NN\n   42/2026)\nSlužbeni tekst kriterija za izbore u zvanja i na radna mjesta.\n\n    Zakon o visokom obrazovanju i znanstvenoj djelatnosti\nPročišćeni tekst Zakona.\n<a href=\"https://www.zakon.hr/z/2332/Zakon-o-visokom-obrazovanju-i-znanstvenoj-djelatnosti\" target=\"_blank\" rel=\"noreferrer\">https://www.zakon.hr/z/2332/Zakon-o-visokom-obrazovanju-i-znanstvenoj-djelatnosti</a>\n\n    Rektorski zbor Republike Hrvatske\nPravilnici, odluke i informacije relevantne za sveučilišni sustav.\n<a href=\"https://www.rektorski-zbor.hr/\" target=\"_blank\" rel=\"noreferrer\">https://www.rektorski-zbor.hr/</a>\n\n\nPriznavanje diploma i kvalifikacija\n     Agencija za znanost i visoko obrazovanje (AZVO)\nInformacije o priznavanju inozemnih visokoškolskih kvalifikacija.\n<a href=\"https://www.azvo.hr/\" target=\"_blank\" rel=\"noreferrer\">https://www.azvo.hr/</a>\n\n    ENIC/NARIC ured Hrvatska\nDetaljne upute za akademsko priznavanje diploma.\n<a href=\"https://www.azvo.hr/hr/enic-naric-ured\" target=\"_blank\" rel=\"noreferrer\">https://www.azvo.hr/hr/enic-naric-ured</a>\n\n\nPlaće i radni uvjeti u znanosti\n    Nezavisni sindikat znanosti i visokog obrazovanja\nInformacije o kolektivnim ugovorima, koeficijentima i kalkulatoru plaća.\n<a href=\"https://www.nsz.hr/\" target=\"_blank\" rel=\"noreferrer\">https://www.nsz.hr/</a></div>"}, {"title": "Povratak u Hrvatsku i useljavanje", "page": 25, "image": null, "body": "<div class=\"pdf-text\">Povratak u Hrvatsku i useljavanje\n    Ministarstvo demografije i useljeništva\nNatječaji i programi potpore usmjereni prema povratnicima i useljenicima.\n<a href=\"https://mdu.gov.hr/\" target=\"_blank\" rel=\"noreferrer\">https://mdu.gov.hr/</a>\n\n    Središnji državni ured za Hrvate izvan Republike Hrvatske\nInformacije za hrvatske državljane i potomke koji žive u inozemstvu.\n<a href=\"https://hrvatiizvanrh.gov.hr/\" target=\"_blank\" rel=\"noreferrer\">https://hrvatiizvanrh.gov.hr/</a>\n\n    EURAXESS Croatia\nPraktične informacije za međunarodne istraživače i njihove obitelji (vize, boravak,\nzdravstveno osiguranje, svakodnevni život).\n<a href=\"https://www.euraxess.hr/\" target=\"_blank\" rel=\"noreferrer\">https://www.euraxess.hr/</a>\n\n\n Porezi i administracija\n    Porezna uprava Republike Hrvatske\nInformacije o poreznoj rezidentnosti, poreznim olakšicama i obvezama.\n<a href=\"https://porezna.gov.hr/\" target=\"_blank\" rel=\"noreferrer\">https://porezna.gov.hr/</a>\n\n    e-Građani\nPortal za pristup elektroničkim uslugama javne uprave.\n<a href=\"https://gov.hr/hr/e-gradjani/1769\" target=\"_blank\" rel=\"noreferrer\">https://gov.hr/hr/e-gradjani/1769</a>\n\n    Hrvatski zavod za mirovinsko osiguranje (HZMO)\nPriznavanje inozemnog staža i ostvarivanje mirovinskih prava.\n<a href=\"https://www.mirovinsko.hr/\" target=\"_blank\" rel=\"noreferrer\">https://www.mirovinsko.hr/</a>\n\n    Hrvatski zavod za zdravstveno osiguranje (HZZO)\nInformacije o zdravstvenom osiguranju nakon povratka.\n<a href=\"https://hzzo.hr/\" target=\"_blank\" rel=\"noreferrer\">https://hzzo.hr/</a></div>"}, {"title": "Financiranje istraživanja i poduzetništvo", "page": 26, "image": null, "body": "<div class=\"pdf-text\">Financiranje istraživanja\n    Agencija za mobilnost i programe Europske unije\n<a href=\"https://www.ampeu.hr/\" target=\"_blank\" rel=\"noreferrer\">https://www.ampeu.hr/</a>\n\n    Hrvatska zaklada za znanost (HRZZ)\nNacionalni natječaji za financiranje istraživačkih projekata.\n<a href=\"https://hrzz.hr/\" target=\"_blank\" rel=\"noreferrer\">https://hrzz.hr/</a>\n\n    Horizon Europe\nProgram Europske unije za istraživanje i inovacije.\n<a href=\"https://research-and-innovation.ec.europa.eu/funding/funding-opportunities/funding-\" target=\"_blank\" rel=\"noreferrer\">https://research-and-innovation.ec.europa.eu/funding/funding-opportunities/funding-</a>\nprogrammes-and-open-calls/horizon-europe_en\n\n    European Research Council (ERC)\nInformacije o ERC grantovima.\n<a href=\"https://erc.europa.eu/\" target=\"_blank\" rel=\"noreferrer\">https://erc.europa.eu/</a>\n\n    COST Actions\nEuropske istraživačke mreže i mogućnosti međunarodnog umrežavanja.\n<a href=\"https://www.cost.eu/\" target=\"_blank\" rel=\"noreferrer\">https://www.cost.eu/</a>\n\n\n\n\nZapošljavanje, samozapošljavanje i poduzetništvo\n    Hrvatski zavod za zapošljavanje (HZZ)\nOpće informacije o zapošljavanju i mjerama aktivne politike zapošljavanja.\n<a href=\"https://www.hzz.hr/\" target=\"_blank\" rel=\"noreferrer\">https://www.hzz.hr/</a>\n\n    Katalog mjera aktivne politike zapošljavanja\nPregled svih aktualnih HZZ mjera.\n<a href=\"https://mjere.hzz.hr/katalog-mjera/mjere-aktivnog-zaposljavanja/\" target=\"_blank\" rel=\"noreferrer\">https://mjere.hzz.hr/katalog-mjera/mjere-aktivnog-zaposljavanja/</a>\n\n    Mjera „Biram Hrvatsku”\nPotpora za samozapošljavanje i povratak hrvatskih državljana iz inozemstva.\n<a href=\"https://mjere.hzz.hr/mjere/biram-hrvatsku/\" target=\"_blank\" rel=\"noreferrer\">https://mjere.hzz.hr/mjere/biram-hrvatsku/</a></div>"}]}, {"id": "penkala", "number": "08", "title": "Udruga Penkala", "summary": "Povezivanje, razumijevanje i osnaživanje hrvatske znanstvene dijaspore.", "sections": [{"title": "Udruga Penkala", "page": 27, "image": null, "body": "<div class=\"pdf-text\">Udruga Penkala:\npovezivanje, razumijevanje i\nosnaživanje hrvatske znanstvene\ndijaspore\n\nUdruga Penkala posljednjih godina razvija niz aktivnosti usmjerenih na\npovezivanje hrvatskih znanstvenika u zemlji i inozemstvu, bolje razumijevanje\npotreba znanstvene dijaspore te stvaranje konkretnih prijedloga za unapređenje\njavnih politika vezanih uz njihov angažman i povratak.\n\nIako je ovaj vodič prvenstveno usmjeren na znanstvenike koji razmišljaju o\npovratku u Hrvatsku, važno je naglasiti da povratak nije jedini oblik doprinosa\nznanstvene dijaspore. Suradnja na projektima, mentoriranje, gostujuća\npredavanja, uključivanje u međunarodne mreže i prijenos znanja također\npredstavljaju vrijedne načine povezivanja s hrvatskim znanstvenim sustavom.\n\nU nastavku donosimo pregled aktivnosti Udruge Penkala koje mogu biti posebno\nkorisne hrvatskim znanstvenicima u inozemstvu i onima koji razmišljaju o\npovratku.</div>"}, {"title": "Mapa Hrvatskih znanstvenika i podcast „Slušalica“", "page": 28, "image": "pdf-images/image-010.png", "body": "<div class=\"pdf-text\">         Mapa Hrvatskih znanstvenika\nJedna od ključnih inicijativa Udruge Penkala je razvoj Mape hrvatskih znanstvenika, digitalne\nplatforme koja okuplja hrvatske istraživače i istraživačice iz Hrvatske i inozemstva.\n\nCilj projekta je:\n     povećati vidljivost hrvatske znanstvene dijaspore,\n     olakšati međusobno povezivanje istraživača,\n     potaknuti nove suradnje,\n     omogućiti razmjenu iskustava i znanja,\n     te stvoriti temelje za bolje razumijevanje potencijala hrvatske znanstvene zajednice izvan\n     granica Hrvatske.\n\n▶ Mapa hrvatskih znanstvenika: <a href=\"https://www.mapa-znanstvenika.hr/\" target=\"_blank\" rel=\"noreferrer\">https://www.mapa-znanstvenika.hr/</a>\n\n\n        Podcast „Slušalica“ – priče znanstvenika povratnika\nKroz svoj znanstveni podcast „Slušalica“, Udruga Penkala nastoji približiti životne i\nprofesionalne priče hrvatskih znanstvenika te otvoriti prostor za razgovor o izazovima i\nprilikama rada u znanosti.\n\nPosebno mjesto zauzima serijal „Znanstvenici povratnici“, koji kroz osobna iskustva istraživača\ndemistificira proces povratka u Hrvatsku. U tim razgovorima gosti otvoreno govore o:\n     motivaciji za odlazak i povratak,\n     iskustvima rada u različitim akademskim sustavima,\n     administrativnim i profesionalnim izazovima,\n     prilagodbi nakon povratka,\n     te preporukama budućim povratnicima.\nPodcast može poslužiti kao vrijedan izvor praktičnih informacija i podrške svima koji razmišljaju\no sličnom životnom i profesionalnom koraku.\n\n▶ <a href=\"https://www.youtube.com/playlist?list=PLPQ-JQ5Gt3niUg6pE0rWpokqeL880RfOr\" target=\"_blank\" rel=\"noreferrer\">Podcast serijal &#x27;Znanstvenici povratnici&#x27;</a>\n▶ <a href=\"https://open.spotify.com/show/3xuQTr8EKP2aVykuEHhCyv\" target=\"_blank\" rel=\"noreferrer\">Spotify kanal Udruge Penkala</a></div>"}, {"title": "Istraživanja o hrvatskoj znanstvenoj dijaspori", "page": 29, "image": "pdf-images/image-011.png", "body": "<div class=\"pdf-text\">       Istraživanja o hrvatskoj znanstvenoj dijaspori\n\nUdruga Penkala aktivno doprinosi stvaranju empirijskih podataka o hrvatskoj znanstvenoj\ndijaspori i znanstvenicima povratnicima.\n\nU suradnji s Institutom za istraživanje migracija (IMIN) te uz sufinanciranje Ministarstva za\ndemografiju i useljeništvo, 2025 i 2026. godine provedeno je istraživanje usmjereno na bolje\nrazumijevanje:\n    obrazaca mobilnosti hrvatskih znanstvenika,\n    njihovih veza s Hrvatskom,\n    različitih oblika angažmana dijaspore,\n    motivacija za povratak,\n    prepreka s kojima se susreću,\n    te uvjeta koji bi mogli potaknuti snažnije uključivanje dijaspore u hrvatski znanstveni\n    sustav.\n\n<a href=\"https://repo.imin.hr/object/imin:232\" target=\"_blank\" rel=\"noreferrer\">Rezultati istraživanja</a> predstavljeni su stručnjacima, donositeljima odluka i široj javnosti s\nciljem da posluže kao podloga za razvoj učinkovitijih politika vezanih uz angažman i povratak\nvisokokvalificiranih stručnjaka.\n▶ Više o projektu: <a href=\"https://udruga-penkala.hr/projekt-mapa-hrvatskih-znanstvenika-povezivanje-i-povratak/\" target=\"_blank\" rel=\"noreferrer\">&#x27;Mapa hrvatskih znanstvenika: povezivanje i povratak</a>\n▶ Rezultati istraživanja\n\nNa temelju provedenih istraživanja i razgovora sa znanstvenicima u Hrvatskoj i inozemstvu,\nUdruga Penkala razvija i zagovara preporuke za unapređenje javnih politika koje se odnose na\nhrvatsku znanstvenu dijasporu.\n\nTeme koje se pritom ističu uključuju:\n   sustavnije praćenje i evaluaciju mjere „Znanstvenik povratnik“,\n   smanjenje administrativnih prepreka pri povratku,\n   veću transparentnost zapošljavanja,\n   razvoj fleksibilnih modela suradnje sa znanstvenom dijasporom,\n   prepoznavanje doprinosa dijaspore i izvan trajnog povratka,\n   te razvoj dugoročne nacionalne strategije angažmana hrvatskih istraživača u inozemstvu.\n\n▶ <a href=\"https://repo.imin.hr/object/imin:233\" target=\"_blank\" rel=\"noreferrer\">Policy recommendations</a></div>"}, {"title": "Povezivanje znanstvenika povratnika i dijaspore", "page": 30, "image": "pdf-images/image-012.png", "body": "<div class=\"pdf-text\">        Povezivanje znanstvenika povratnika i dijaspore\n\nUdruga Penkala pokušava biti poveznica i pružiti pomoć onima koji razmišljaju o\npovratku. Iz tog razloga kreirali smo internu listu znanstvenika povratnike po\ninstitucijama, te Slack kanal za upite.\n\nStoga:\n    Ako razmišljate o povratku i ovaj vodič nije odgovorio na sva vaša pitanja javite\n   nam se sa upitima na <a href=\"mailto:info@udruga-penkala.hr\" target=\"_blank\" rel=\"noreferrer\">info@udruga-penkala.hr</a> pa ćemo vam pokušati pomoći.\n   Ako ste jedan od povratnika i spremni ste odgovoriti na pitanja oko vlastitog\n   iskustva, javite nam se na <a href=\"mailto:info@udruga-penkala.hr\" target=\"_blank\" rel=\"noreferrer\">info@udruga-penkala.hr</a> da vas dodamo u svoju\n   internu listu koju koristimo za pomoć potencijalnim povratnicima. Ukoliko nam\n   se javi netko tko se želi vratiti na instituciju kao i vi onda vas možemo povezati.\n\nTakođer ukoliko niste povratnik, ali ste znanstvenik u dijaspori koji bi se više volio\npovezati za hrvatskim znanstvenicima u svojoj državi - javite nam se da pokušamo\nzajedno organizirati lokalno okupljanje hrvatskih znanstvenika u vašoj državi.</div>"}]}];

const nav = document.querySelector("#chapterNav");
const mount = document.querySelector("#chapterMount");
const count = document.querySelector("#sectionCount");
const searchInput = document.querySelector("#searchInput");
const sidebar = document.querySelector("#sidebar");
let currentId = guide[0].id;
let query = "";
function stripHtml(value) { const template = document.createElement("template"); template.innerHTML = value; return template.content.textContent || ""; }
function normalize(value) { return value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, ""); }
function highlightPlain(value) { if (!query.trim()) return value; const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); return value.replace(new RegExp(`(${escaped})`, "gi"), "<mark>$1</mark>"); }
function chapterMatches(chapter) { if (!query.trim()) return true; const haystack = normalize([chapter.title, chapter.summary, ...chapter.sections.flatMap((section) => [section.title, stripHtml(section.body)])].join(" ")); return haystack.includes(normalize(query)); }
function filteredSections(chapter) { if (!query.trim()) return chapter.sections; return chapter.sections.filter((section) => normalize(`${section.title} ${stripHtml(section.body)}`).includes(normalize(query))); }
function renderNav() { nav.innerHTML = guide.map((chapter) => { const hidden = chapterMatches(chapter) ? "" : "hidden"; const label = chapter.navLabel || `Poglavlje ${chapter.number}`; return `<button class="nav-button ${chapter.id === currentId ? "active" : ""}" data-id="${chapter.id}" type="button" ${hidden}><span>${label}</span><strong>${chapter.title}</strong></button>`; }).join(""); }
function renderChapter(openFirst = true) { const chapter = guide.find((item) => item.id === currentId) || guide[0]; const sections = filteredSections(chapter); count.textContent = `${sections.length} ${sections.length === 1 ? "odjeljak" : "odjeljaka"}`; if (!sections.length) { mount.innerHTML = `<div class="empty">Nema rezultata u ovom poglavlju. Odaberite drugo poglavlje ili promijenite pojam pretraživanja.</div>`; return; } mount.innerHTML = `<article><header class="chapter-header"><span class="chapter-kicker">${chapter.navLabel || `Poglavlje ${chapter.number}`}</span><h2 class="chapter-title">${highlightPlain(chapter.title)}</h2><p class="chapter-summary">${highlightPlain(chapter.summary)}</p></header><div class="section-list">${sections.map((section, index) => `<details ${openFirst && index === 0 ? "open" : ""}><summary>${highlightPlain(section.title)} <span class="page-chip">str. ${String(section.page).padStart(2, "0")}</span></summary><div class="section-body">${section.image ? `<figure class="section-figure"><img src="assets/${section.image}" alt="Vizual iz PDF vodiča"></figure>` : ""}${section.body}</div></details>`).join("")}</div></article>`; }
function selectChapter(id) { currentId = id; renderNav(); renderChapter(); sidebar.classList.remove("open"); document.querySelector("#content").focus({ preventScroll: true }); }
nav.addEventListener("click", (event) => { const button = event.target.closest("button[data-id]"); if (button) selectChapter(button.dataset.id); });
searchInput.addEventListener("input", (event) => { query = event.target.value.trim(); const visible = guide.filter(chapterMatches); if (visible.length && !visible.some((chapter) => chapter.id === currentId)) currentId = visible[0].id; renderNav(); renderChapter(Boolean(query)); });
document.querySelector("#expandAll").addEventListener("click", () => document.querySelectorAll("details").forEach((item) => { item.open = true; }));
document.querySelector("#collapseAll").addEventListener("click", () => document.querySelectorAll("details").forEach((item) => { item.open = false; }));
document.querySelector("#toggleNav").addEventListener("click", () => sidebar.classList.toggle("open"));
document.addEventListener("keydown", (event) => { if (event.key === "Escape") sidebar.classList.remove("open"); });
renderNav();
renderChapter();
